"""Billing webhook handling."""

from src.billing.invoices import InvoiceRepository
from src.billing.payment_gateway import PaymentGateway
from src.common.events import EventBus, EventEnvelope, PAYMENT_WEBHOOK_ACCEPTED


class PaymentWebhookVerifier:
    """Validates payment webhook signatures."""

    def __init__(self, gateway: PaymentGateway | None = None) -> None:
        self.gateway = gateway or PaymentGateway()

    def verify(self, payload: bytes, signature: str) -> bool:
        return self.gateway.verify_signature(payload, signature)


class BillingWebhookController:
    """Controller for provider callbacks."""

    def __init__(
        self,
        verifier: PaymentWebhookVerifier | None = None,
        repository: InvoiceRepository | None = None,
        event_bus: EventBus | None = None,
    ) -> None:
        self.verifier = verifier or PaymentWebhookVerifier()
        self.repository = repository or InvoiceRepository()
        self.event_bus = event_bus or EventBus()

    def receive(self, payload: bytes, signature: str) -> dict:
        if not self.verifier.verify(payload, signature):
            return {"status": 401, "error": "invalid provider signature"}
        self.repository.mark_retry_requested("invoice-123")
        self.event_bus.publish(EventEnvelope(PAYMENT_WEBHOOK_ACCEPTED, {"invoice_id": "invoice-123"}))
        return {"status": 202}

"""Invoice retry policy."""

from dataclasses import dataclass

from src.common.settings import load_retry_policy


@dataclass(frozen=True)
class InvoiceRetryPolicy:
    initial_delay_seconds: int
    max_attempts: int
    backoff_multiplier: int


def load_invoice_retry_policy() -> InvoiceRetryPolicy:
    raw = load_retry_policy()
    return InvoiceRetryPolicy(
        initial_delay_seconds=raw["initial_delay_seconds"],
        max_attempts=raw["max_attempts"],
        backoff_multiplier=raw.get("backoff_multiplier", 2),
    )

"""Domain event primitives."""

from dataclasses import dataclass
from typing import Callable


ORDER_CANCELLED = "order.cancelled"
PAYMENT_WEBHOOK_ACCEPTED = "billing.webhook.accepted"
INVOICE_RETRY_REQUESTED = "billing.invoice.retry_requested"


@dataclass(frozen=True)
class EventEnvelope:
    """Event wrapper shared by producers and consumers."""

    name: str
    payload: dict


class EventBus:
    """In-memory event bus for the fixture."""

    def __init__(self) -> None:
        self._handlers: dict[str, list[Callable[[EventEnvelope], None]]] = {}

    def subscribe(self, name: str, handler: Callable[[EventEnvelope], None]) -> None:
        self._handlers.setdefault(name, []).append(handler)

    def publish(self, event: EventEnvelope) -> None:
        for handler in self._handlers.get(event.name, []):
            handler(event)

"""Event-driven notification dispatch."""

from src.common.events import EventEnvelope, INVOICE_RETRY_REQUESTED, ORDER_CANCELLED
from src.notifications.email import EmailSender
from src.notifications.templates import TEMPLATE_INVOICE_RETRY, TEMPLATE_ORDER_CANCELLED


class NotificationDispatcher:
    """Routes events to email templates."""

    def __init__(self, sender: EmailSender | None = None) -> None:
        self.sender = sender or EmailSender()

    def handle(self, event: EventEnvelope) -> None:
        if event.name == ORDER_CANCELLED:
            self.sender.send("ops@example.com", TEMPLATE_ORDER_CANCELLED, event.payload)
        if event.name == INVOICE_RETRY_REQUESTED:
            self.sender.send("billing@example.com", TEMPLATE_INVOICE_RETRY, event.payload)

